const frozenGuardianSheet=new Image();frozenGuardianSheet.assetSrc='assets/frozen-guardian-v1.png';
function frozenGuardianFactor(e){if(e.species!=='r5e2'||e.hp<=0||e.dotTick||e.reactionStun>0)return 1;if(e.attack?.pattern==='frozenCleave')return e.struck?1.4:1;if(typeof classHitKind==='undefined'||classHitKind!=='normal'||!Number.isFinite(e.guardAngle))return 1;let dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy);return d>0&&(dx*Math.cos(e.guardAngle)+dy*Math.sin(e.guardAngle))/d>=.5-1e-8?.35:1;}
const frozenGuardianHitBase=hit;hit=(e,d)=>frozenGuardianHitBase(e,d*frozenGuardianFactor(e));
function beginFrozenGuardian(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.guardAngle=angle;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'frozenCleave',bespoke:true,windup:1.1,angle,origin:{x:e.x,y:e.y},fired:false};}
function frozenGuardianContains(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,c=Math.cos(a.angle),s=Math.sin(a.angle),along=dx*c+dy*s,side=-dx*s+dy*c;return along>=0-1e-8&&along<=160+1e-8&&Math.abs(side)<=45+1e-8;}
const frozenGuardianAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e2')return frozenGuardianAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='frozenCleave'){
  e.guardTurn=(e.guardTurn||0)-dt;if(e.guardTurn<=0||!Number.isFinite(e.guardAngle)){e.guardAngle=Math.atan2(p.y-e.y,p.x-e.x);e.guardTurn=1.2;e.facing=Math.cos(e.guardAngle)-Math.sin(e.guardAngle)<0?-1:1;}
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=155&&clear){beginFrozenGuardian(e);return;}e.state='idle';if(d>800&&!e.aware||d<=105)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,65*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,20)>.1?'walk':'idle';}}return;
 }
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=1.1){a.fired=true;e.struck=true;if(frozenGuardianContains(a,p)&&lineClear(a.origin,p))hurt(68);burst(e.x+Math.cos(a.angle)*105,e.y+Math.sin(a.angle)*105,65,'#b1e7f1');playSound('impact',e.x,e.y);}
 if(e.elapsed>=2.5){e.attack=null;e.state='idle';e.t=2.5;e.guardTurn=0;}
};
const frozenGuardianDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r5e2'||!frozenGuardianSheet.complete||!frozenGuardianSheet.naturalWidth||!frozenGuardianSheet.naturalHeight)return frozenGuardianDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='frozenCleave')f={row:2,col:e.elapsed<.8?0:e.elapsed<1.1?1:e.elapsed<1.8?2:3};let q=project(e.x,e.y),sw=frozenGuardianSheet.naturalWidth/4,sh=frozenGuardianSheet.naturalHeight/3,w=220,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,frozenGuardianSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.86,w,h);else ctx.drawImage(frozenGuardianSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.86,w,h);ctx.restore();return true;
};
const frozenGuardianSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e2'?145:frozenGuardianSizeBase(e);
const frozenGuardianGroundBase=drawGroundEffects;drawGroundEffects=()=>{frozenGuardianGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e2'):enemies)){if(e.species!=='r5e2'||e.hp<=0||!visibleAt(e.x,e.y))continue;let a=e.attack;ctx.save();if(a?.pattern==='frozenCleave'){if(!a.fired||e.elapsed<1.3){let c=Math.cos(a.angle),s=Math.sin(a.angle);ctx.strokeStyle=a.fired?'#e3fbff':'#eba470';ctx.fillStyle='#d68c4622';ctx.lineWidth=2;ctx.beginPath();for(let [i,[along,side]]of [[0,-45],[160,-45],[160,45],[0,45]].entries()){let q=project(a.origin.x+c*along-s*side,a.origin.y+s*along+c*side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.fill();ctx.stroke();}else groundRing(e.x,e.y,48,'#f2cb7e',2);}else if(Number.isFinite(e.guardAngle)){ctx.strokeStyle='#8fdef1';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=12;i++){let angle=e.guardAngle-Math.PI/3+i*Math.PI/18,q=project(e.x+Math.cos(angle)*55,e.y+Math.sin(angle)*55);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.stroke();}ctx.restore();}};
